import{_ as r,a0 as o,w as d,s as p,ao as n,I as e,x as i,a1 as a,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"使用子模块和子树来管理 Git 项目 | LCTT x X-CMD","titleTemplate":false,"description":"使用子模块和子树来管理 Git 项目 | LCTT (202005) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用子模块和子树来管理 Git 项目 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用子模块和子树来管理 Git 项目 | LCTT (202005) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202005/20200506 Managing Git projects with submodules and subtrees","title":"使用子模块和子树来管理 Git 项目","tag":"202005","desc":""},"relativePath":"202005/20200506 Managing Git projects with submodules and subtrees.md","filePath":"[post].md"}'),u={name:"202005/20200506 Managing Git projects with submodules and subtrees.md"};function g(h,t,b,k,m,f){const s=o("Link");return d(),p("div",null,[t[35]||(t[35]=n('<h1 id="使用子模块和子树来管理-git-项目" tabindex="-1">使用子模块和子树来管理 Git 项目 <a class="header-anchor" href="#使用子模块和子树来管理-git-项目" aria-label="Permalink to “使用子模块和子树来管理 Git 项目”">​</a></h1><blockquote><p>使用子模块和子树来帮助你管理多个存储库中共有的子项目。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202005/23/201323myyhob22eg2y2jqt.jpg" alt=""></p><p>如果你参与了开源项目的开发，那么你很可能已经用了 Git 来管理你的源码。你可能遇到过有很多依赖和/或子项目的项目。你是如何管理它们的？</p><p>对于一个开源组织，要实现社区<strong>和</strong>产品的单一来源文档和依赖管理比较棘手。文档和项目往往会碎片化和变得冗余，这致使它们很难维护。</p><h3 id="必要性" tabindex="-1">必要性 <a class="header-anchor" href="#必要性" aria-label="Permalink to “必要性”">​</a></h3><p>假设你想把单个项目作为一个存储库内的子项目，传统的方法是把该项目复制到父存储库中，但是，如果你想要在多个父项目中使用同一个子项目呢？如果把子项目复制到所有父项目中，当有更新时，你都要在每个父项目中做修改，这是不太可行的。这会导致父项目中的冗余和数据不一致，使更新和维护子项目变得很困难。</p><h3 id="git-子模块和子树" tabindex="-1">Git 子模块和子树 <a class="header-anchor" href="#git-子模块和子树" aria-label="Permalink to “Git 子模块和子树”">​</a></h3><p>如果你可以用一条命令把一个项目放进另一个项目中，会怎样呢？如果你随时可以把一个项目作为子项目添加到任意数目的项目中，并可以同步更新修改呢？Git 提供了这类问题的解决方案：Git <ruby>子模块<rt>submodule</rt></ruby>和 Git <ruby>子树<rt>subtree</rt></ruby>。创建这些工具的目的是以更加模块化的水平来支持共用代码的开发工作流，旨在 Git 存储库<ruby>源码管理<rt>source-code management</rt></ruby>（SCM）与它下面的子树之间架起一座桥梁。</p><p><img src="https://opensource.com/sites/default/files/uploads/640px-bialbero_di_casorzo.jpg" alt="Cherry tree growing on a mulberry tree" title="Cherry tree growing on a mulberry tree"></p><p><em>生长在桑树上的樱桃树</em></p><p>下面是本文要详细介绍的概念的一个真实应用场景。如果你已经很熟悉树形结构，这个模型看起来是下面这样：</p><p><img src="https://opensource.com/sites/default/files/subtree_0.png" alt="Tree with subtrees" title="Tree with subtrees"></p><h3 id="git-子模块是什么" tabindex="-1">Git 子模块是什么？ <a class="header-anchor" href="#git-子模块是什么" aria-label="Permalink to “Git 子模块是什么？”">​</a></h3>',14)),e("p",null,[t[1]||(t[1]=i("Git 在它默认的包中提供了子模块，子模块可以把 Git 存储库嵌入到其他存储库中。确切地说，Git 子模块指向子树中的某次提交。下面是我 ",-1)),a(s,{href:"https://github.com/manaswinidas/Docs-test/"},{default:l(()=>[...t[0]||(t[0]=[i("Docs-test",-1)])]),_:1}),t[2]||(t[2]=i(" GitHub 存储库中的 Git 子模块的样子：",-1))]),t[36]||(t[36]=e("p",null,[e("img",{src:"https://opensource.com/sites/default/files/uploads/git-submodules_github.png",alt:"Git submodules screenshot",title:"Git submodules screenshot"})],-1)),e("p",null,[a(s,{href:"mailto:folder@commitId"},{default:l(()=>[...t[3]||(t[3]=[i("文件夹@提交 Id",-1)])]),_:1}),t[4]||(t[4]=i(" 格式表明这个存储库是一个子模块，你可以直接点击文件夹进入该子树。名为 ",-1)),t[5]||(t[5]=e("code",null,".gitmodules",-1)),t[6]||(t[6]=i(" 的配置文件包含所有子模块存储库的详细信息。我的存储库的 ",-1)),t[7]||(t[7]=e("code",null,".gitmodules",-1)),t[8]||(t[8]=i(" 文件如下：",-1))]),t[37]||(t[37]=n(`<p><img src="https://opensource.com/sites/default/files/uploads/gitmodules.png" alt="Screenshot of .gitmodules file" title="Screenshot of .gitmodules file"></p><p>你可以用下面的命令在你的存储库中使用 Git 子模块：</p><h4 id="克隆一个存储库并加载子模块" tabindex="-1">克隆一个存储库并加载子模块 <a class="header-anchor" href="#克隆一个存储库并加载子模块" aria-label="Permalink to “克隆一个存储库并加载子模块”">​</a></h4><p>克隆一个含有子模块的存储库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone --recursive &lt;URL to Git repo&gt;</span></span></code></pre></div><p>如果你之前已经克隆了存储库，现在想加载它的子模块：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git submodule update --init</span></span></code></pre></div><p>如果有嵌套的子模块：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git submodule update --init --recursive</span></span></code></pre></div><h4 id="下载子模块" tabindex="-1">下载子模块 <a class="header-anchor" href="#下载子模块" aria-label="Permalink to “下载子模块”">​</a></h4><p>串行地连续下载多个子模块是很枯燥的工作，所以 <code>clone</code> 和 <code>submodule update</code> 会支持 <code>--jobs</code> （或 <code>-j</code>）参数：</p><p>例如，想一次下载 8 个子模块，使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git submodule update --init --recursive -j 8</span></span>
<span class="line"><span>$ git clone --recursive --jobs 8 &lt;URL to Git repo&gt;</span></span></code></pre></div><h4 id="拉取子模块" tabindex="-1">拉取子模块 <a class="header-anchor" href="#拉取子模块" aria-label="Permalink to “拉取子模块”">​</a></h4><p>在运行或构建父项目之前，你需要确保依赖的子项目都是最新的。</p><p>拉取子模块的所有修改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git submodule update --remote</span></span></code></pre></div><h4 id="使用子模块创建存储库" tabindex="-1">使用子模块创建存储库： <a class="header-anchor" href="#使用子模块创建存储库" aria-label="Permalink to “使用子模块创建存储库：”">​</a></h4><p>向一个父存储库添加子树：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git submodule add &lt;URL to Git repo&gt;</span></span></code></pre></div><p>初始化一个已存在的 Git 子模块：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git submodule init</span></span></code></pre></div><p>你也可以通过为 <code>submodule update</code> 命令添加 <code>--update</code> 参数在子模块中创建分支和追踪提交：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git submodule update --remote</span></span></code></pre></div><h4 id="更新子模块的提交" tabindex="-1">更新子模块的提交 <a class="header-anchor" href="#更新子模块的提交" aria-label="Permalink to “更新子模块的提交”">​</a></h4><p>上面提到过，一个子模块就是一个指向子树中某次提交的链接。如果你想更新子模块的提交，不要担心。你不需要显式地指定最新的提交。你只需要使用通用的 <code>submodule update</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git submodule update</span></span></code></pre></div><p>就像你平时创建父存储库和把父存储库推送到 GitHub 那样添加和提交就可以了。</p><h4 id="从一个父存储库中删除一个子模块" tabindex="-1">从一个父存储库中删除一个子模块 <a class="header-anchor" href="#从一个父存储库中删除一个子模块" aria-label="Permalink to “从一个父存储库中删除一个子模块”">​</a></h4><p>仅仅手动删除一个子项目文件夹不会从父项目中移除这个子项目。想要删除名为 <code>childmodule</code> 的子模块，使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git rm -f childmodule</span></span></code></pre></div><p>虽然 Git 子模块看起来很容易上手，但是对于初学者来说，有一定的使用门槛。</p><h3 id="git-子树是什么" tabindex="-1">Git 子树是什么？ <a class="header-anchor" href="#git-子树是什么" aria-label="Permalink to “Git 子树是什么？”">​</a></h3><p>Git <ruby>子树<rt> subtree</rt></ruby>，是在 Git 1.7.11 引入的，让你可以把任何存储库的副本作为子目录嵌入另一个存储库中。它是 Git 项目可以注入和管理项目依赖的几种方法之一。它在常规的提交中保存了外部依赖信息。Git 子树提供了整洁的集成点，因此很容易复原它们。</p>`,34)),e("p",null,[t[11]||(t[11]=i("如果你参考 ",-1)),a(s,{href:"https://help.github.com/en/github/using-git/about-git-subtree-merges"},{default:l(()=>[...t[9]||(t[9]=[i("GitHub 提供的子树教程",-1)])]),_:1}),t[12]||(t[12]=i("来使用子树，那么无论你什么时候添加子树，在本地都不会看到 ",-1)),t[13]||(t[13]=e("code",null,".gittrees",-1)),t[14]||(t[14]=i(" 配置文件。这让我们很难分辨哪个是子树，因为它们看起来很像普通的文件夹，但是它们却是子树的副本。默认的 Git 包中不提供带 ",-1)),t[15]||(t[15]=e("code",null,".gittrees",-1)),t[16]||(t[16]=i(" 配置文件的 Git 子树版本，因此如果你想要带 ",-1)),t[17]||(t[17]=e("code",null,".gittrees",-1)),t[18]||(t[18]=i(" 配置文件的 git-subtree 命令，必须从 Git 源码存储库的 ",-1)),a(s,{href:"https://github.com/git/git/tree/master/contrib/subtree"},{default:l(()=>[...t[10]||(t[10]=[i("/contrib/subtree 文件夹",-1)])]),_:1}),t[19]||(t[19]=i(" 下载 git-subtree。",-1))]),t[38]||(t[38]=n(`<p>你可以像克隆其他常规的存储库那样克隆任何含有子树的存储库，但由于在父存储库中有整个子树的副本，因此克隆过程可能会持续很长时间。</p><p>你可以用下面的命令在你的存储库中使用 Git 子树。</p><h4 id="向父存储库中添加一个子树" tabindex="-1">向父存储库中添加一个子树 <a class="header-anchor" href="#向父存储库中添加一个子树" aria-label="Permalink to “向父存储库中添加一个子树”">​</a></h4><p>想要向父存储库中添加一个子树，首先你需要执行 <code>remote add</code>，之后执行 <code>subtree add</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git remote add remote-name &lt;URL to Git repo&gt;</span></span>
<span class="line"><span>$ git subtree add --prefix=folder/ remote-name &lt;URL to Git repo&gt; subtree-branchname</span></span></code></pre></div><p>上面的命令会把整个子项目的提交历史合并到父存储库。</p><h4 id="向子树推送修改以及从子树拉取修改" tabindex="-1">向子树推送修改以及从子树拉取修改 <a class="header-anchor" href="#向子树推送修改以及从子树拉取修改" aria-label="Permalink to “向子树推送修改以及从子树拉取修改”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git subtree push-all</span></span></code></pre></div><p>或者</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git subtree pull-all</span></span></code></pre></div><h3 id="你应该使用哪个" tabindex="-1">你应该使用哪个？ <a class="header-anchor" href="#你应该使用哪个" aria-label="Permalink to “你应该使用哪个？”">​</a></h3><p>任何工具都有优缺点。下面是一些可能会帮助你决定哪种最适合你的特性：</p><ul><li>Git 子模块的存储库占用空间更小，因为它们只是指向子项目的某次提交的链接，而 Git 子树保存了整个子项目及其提交历史。</li><li>Git 子模块需要在服务器中可访问，但子树是去中心化的。</li><li>Git 子模块大量用于基于组件的开发，而 Git 子树多用于基于系统的开发。</li></ul><p>Git 子树并不是 Git 子模块的直接可替代项。有明确的说明来指导我们该使用哪种。如果有一个归属于你的外部存储库，使用场景是向它回推代码，那么就使用 Git 子模块，因为推送代码更容易。如果你有第三方代码，且不会向它推送代码，那么使用 Git 子树，因为拉取代码更容易。</p><p>自己尝试使用 Git 子树和子模块，然后在评论中留下你的使用感想。</p><hr>`,16)),e("p",null,[t[21]||(t[21]=i("via: ",-1)),a(s,{href:"https://opensource.com/article/20/5/git-submodules-subtrees"},{default:l(()=>[...t[20]||(t[20]=[i("https://opensource.com/article/20/5/git-submodules-subtrees",-1)])]),_:1})]),e("p",null,[t[26]||(t[26]=i("作者：",-1)),a(s,{href:"https://opensource.com/users/manaswinidas"},{default:l(()=>[...t[22]||(t[22]=[i("Manaswini Das",-1)])]),_:1}),t[27]||(t[27]=i(" 选题：",-1)),a(s,{href:"https://github.com/lujun9972"},{default:l(()=>[...t[23]||(t[23]=[i("lujun9972",-1)])]),_:1}),t[28]||(t[28]=i(" 译者：",-1)),a(s,{href:"https://github.com/lxbwolf"},{default:l(()=>[...t[24]||(t[24]=[i("lxbwolf",-1)])]),_:1}),t[29]||(t[29]=i(" 校对：",-1)),a(s,{href:"https://github.com/wxy"},{default:l(()=>[...t[25]||(t[25]=[i("wxy",-1)])]),_:1})]),e("p",null,[t[32]||(t[32]=i("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[30]||(t[30]=[i("LCTT",-1)])]),_:1}),t[33]||(t[33]=i(" 原创编译，",-1)),a(s,{href:"https://linux.cn/"},{default:l(()=>[...t[31]||(t[31]=[i("Linux中国",-1)])]),_:1}),t[34]||(t[34]=i(" 荣誉推出",-1))])])}const C=r(u,[["render",g]]);export{y as __pageData,C as default};
